/** Craft name (lib/data.ts) -> logo slug. */
export const CRAFT_LOGOS: Record<string, string> = {
  "TypeScript": "typescript",
  "JavaScript": "javascript",
  "Python": "python",
  "React": "react",
  "Next.js": "nextdotjs",
  "Node.js": "nodedotjs",
  "PostgreSQL": "postgresql",
  "MongoDB": "mongodb",
  "Git": "git",
  "GitHub": "github",
  "HTML": "html5",
  "CSS": "css",
  "Tailwind CSS": "tailwindcss",
  "Material UI": "mui",
  "Vite": "vite",
  "Electron": "electron",
  "Capacitor": "capacitor",
  "Postman": "postman",
  "Vercel": "vercel",
  "Docker": "docker",
  "FastAPI": "fastapi",
  "LangChain": "langchain",
  "Prisma": "prisma",
  "Supabase": "supabase",
  "Redis": "redis",
  "Kubernetes": "kubernetes",
  "GraphQL": "graphql",
  "Apache Kafka": "apachekafka",
  "RabbitMQ": "rabbitmq",
  "NGINX": "nginx",
  "Linux": "linux",
  "ASP.NET Core": "dotnet",
  ".NET": "dotnet",
  "C#": "dotnet",
  "Express": "express",
  "GitHub Actions": "githubactions",
  "Zod": "zod",
  "Swagger": "swagger",
  "Google Cloud": "googlecloud",
  "Cloudflare": "cloudflare",
  "MySQL": "mysql",
  "SQLite": "sqlite",
  "Jest": "jest",
};

export type LogoSlug = keyof typeof LOGOS;

export function logoFor(craft: string): Logo | undefined {
  const slug = CRAFT_LOGOS[craft];
  return slug ? LOGOS[slug] : undefined;
}

export function logoBySlug(slug: string): Logo | undefined {
  return LOGOS[slug];
}

/**
 * Renders an authentic brand mark.
 * `tone` keeps the official brand colour; `mono` inherits currentColor.
 */
export default function TechLogo({
  craft,
  slug,
  size = 26,
  mono = false,
  className = '',
}: {
  craft?: string;
  slug?: string;
  size?: number;
  mono?: boolean;
  className?: string;
}) {
  const logo = craft ? logoFor(craft) : slug ? logoBySlug(slug) : undefined;
  if (!logo) return null;
  return (
    <svg
      className={'tech-logo ' + className}
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill={mono ? 'currentColor' : '#' + logo.h}
      role="img"
      aria-label={logo.t}
      focusable="false"
    >
      <path d={logo.p} />
    </svg>
  );
}
